import math


def normalize(points):
    mid_hip = [(points['left_hip'][i] + points['right_hip'][i]) / 2 for i in (0, 1)]
    mid_sh = [(points['left_shoulder'][i] + points['right_shoulder'][i]) / 2 for i in (0, 1)]
    torso = math.hypot(mid_sh[0] - mid_hip[0], mid_sh[1] - mid_hip[1])
    if torso < 1e-6:
        torso = 1e-6
    return {k: [(v[0] - mid_hip[0]) / torso, (v[1] - mid_hip[1]) / torso]
            for k, v in points.items()}

