def find_deviation_segments(diffs, threshold, min_frames):
    segments = []
    in_seg = False
    start = 0
    for i, v in enumerate(diffs):
        if v > threshold and not in_seg:
            in_seg = True
            start = i
        elif v <= threshold and in_seg:
            in_seg = False
            if i - start >= min_frames:
                segments.append((start, i - 1))
    if in_seg and len(diffs) - start >= min_frames:
        segments.append((start, len(diffs) - 1))
    return segments
